with q as (select * from (values
('pcac-lc526-probation-duration-17','LC nº 526/2026 — estágio probatório','Qual é a duração do estágio probatório dos policiais civis, conforme o art. 73 da LC nº 129/2004, com redação atual?','(A) 12 meses.\n(B) 18 meses.\n(C) 2 anos.\n(D) 3 anos.\n(E) 5 anos.','D','O art. 73 estabelece estágio probatório de três anos.'),
('pcac-lc526-probation-appeal-18','LC nº 526/2026 — recurso no estágio','Formalizada proposta de exoneração ao final do estágio probatório, qual prazo o servidor tem para apresentar recurso administrativo?','(A) 2 dias úteis.\n(B) 5 dias.\n(C) 10 dias.\n(D) 15 dias.\n(E) 30 dias.','B','O art. 73, § 7º, assegura prazo de cinco dias para recurso, pessoalmente ou por procurador habilitado.'),
('pcac-lc526-appeal-effects-19','LC nº 526/2026 — efeitos do recurso','O recurso administrativo contra proposta de exoneração no estágio probatório é recebido:','(A) Apenas no efeito devolutivo.\n(B) Apenas no efeito suspensivo.\n(C) Nos efeitos suspensivo e devolutivo.\n(D) Sem efeito algum.\n(E) Com efeito vinculante judicial.','C','O art. 73, § 10, estabelece expressamente os efeitos suspensivo e devolutivo.'),
('pcac-lc526-course-absence-20','LC nº 526/2026 — frequência no curso','Conforme o art. 79-B, constitui hipótese de exoneração por não preenchimento de requisito essencial do estágio probatório:','(A) Exatamente 10% de faltas justificadas.\n(B) Mais de 25% de faltas injustificadas em qualquer disciplina.\n(C) Uma falta justificada.\n(D) Atraso isolado sem previsão regulamentar.\n(E) Nota alta em disciplina prática.','B','A lei usa o critério superior a 25% de faltas injustificadas em qualquer disciplina.'),
('pcac-lc526-course-termination-21','LC nº 526/2026 — reprovação','A reprovação em qualquer disciplina do curso específico de formação policial pode resultar em:','(A) Apenas advertência verbal.\n(B) Suspensão automática por 30 dias.\n(C) Exoneração por não preenchimento de requisito essencial do estágio probatório.\n(D) Promoção postergada por um ano.\n(E) Transferência obrigatória.','C','O art. 79-B, I, alínea a, prevê exoneração nessa hipótese.'),
('pcac-lc526-stability-22','LC nº 526/2026 — estabilidade','A aquisição da estabilidade depende de três anos de efetivo exercício e:','(A) Apenas do decurso do tempo.\n(B) Avaliação especial de desempenho por comissão, considerando relatórios do estágio e aproveitamento no curso de formação.\n(C) Aprovação em nova prova objetiva.\n(D) Indicação do chefe imediato, exclusivamente.\n(E) Promoção para a classe seguinte.','B','O art. 74, parágrafo único, exige avaliação especial de desempenho por comissão, considerando relatórios do estágio e aproveitamento no curso.'),
('pcac-lc526-first-assignment-23','LC nº 526/2026 — primeira lotação','Qual critério define a primeira lotação do servidor após o curso de formação?','(A) Nota final do concurso público, exclusivamente.\n(B) Escolha livre sem critérios.\n(C) Classificação final obtida nas avaliações do curso específico de formação.\n(D) Antiguidade no serviço público anterior.\n(E) Sorteio obrigatório.','C','O art. 79-C, § 1º, determina que a classificação final no curso define a primeira lotação.'),
('pcac-lc526-reporting-24','LC nº 526/2026 — apresentação na unidade','Após a publicação oficial do ato de lotação inicial, qual o prazo para o servidor se apresentar na unidade policial de destino?','(A) 24 horas corridas.\n(B) 2 dias corridos.\n(C) Até 3 dias úteis, contados do primeiro dia útil subsequente à publicação.\n(D) 5 dias úteis.\n(E) 10 dias úteis.','C','O art. 79, parágrafo único, prevê até três dias úteis, contados do primeiro dia útil subsequente à publicação.')
) as t(external_item_key,subtopic,question_text,options_text,answer,explanation))
