select '43712f0d-aad2-48b5-a685-6937551f2d74','d204d14f-8aa6-4c57-92ad-3fb3c3e901f1',external_item_key,'Norte Concursos — treino autoral PC-AC 2026',2026,'Oficial Investigador de Polícia','AUTORAL','Legislação Institucional',subtopic,question_text||E'\n\n'||options_text,answer,explanation,'média','active',true,'AC','Polícia Civil','Oficial Investigador de Polícia',subtopic,external_item_key,'pcac-2026-'||external_item_key,jsonb_build_object('kind','didactic_original','authored',true,'target_exam','PC-AC 2026 — Oficial Investigador de Polícia','not_official_exam',true,'license_note','Questão autoral inédita; não é item oficial da IDECAN','linked_study_material_slug','pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','source_material_slug','pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','source_exam_reference','Edital nº 001 SEAD/PCAC, de 05/11/2026, Anexo III') from q
